create extension if not exists pgcrypto;
create table if not exists teacher_classes(id uuid primary key default gen_random_uuid(),owner_key text not null,school_year int not null,grade int not null check(grade between 1 and 6),class_number int not null,name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists class_students(id uuid primary key default gen_random_uuid(),owner_key text not null,class_id uuid not null references teacher_classes(id) on delete cascade,student_number int not null,display_name text not null,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(class_id,student_number));
create table if not exists attendance_records(id uuid primary key default gen_random_uuid(),owner_key text not null,class_id uuid not null references teacher_classes(id) on delete cascade,student_id uuid not null references class_students(id),attendance_date date not null,status text not null check(status in ('미확인','출석','결석','지각','조퇴','결과')),note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(class_id,student_id,attendance_date));
create table if not exists class_assignments(id uuid primary key default gen_random_uuid(),owner_key text not null,class_id uuid not null references teacher_classes(id) on delete cascade,title text not null,subject text,description text,assigned_date date,due_date date not null,status text not null check(status in ('진행 중','마감','보관')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists submission_records(id uuid primary key default gen_random_uuid(),owner_key text not null,assignment_id uuid not null references class_assignments(id) on delete cascade,student_id uuid not null references class_students(id),status text not null check(status in ('미확인','제출','미제출','늦게 제출','재제출 필요')),note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assignment_id,student_id));
alter table teacher_classes enable row level security;alter table class_students enable row level security;alter table attendance_records enable row level security;alter table class_assignments enable row level security;alter table submission_records enable row level security;
grant usage on schema public to anon, authenticated;
grant select, insert, update, delete on table teacher_classes,class_students,attendance_records,class_assignments,submission_records to anon, authenticated;
do $$ declare t text; begin foreach t in array array['teacher_classes','class_students','attendance_records','class_assignments','submission_records'] loop execute format('drop policy if exists owner_access on %I',t);execute format('create policy owner_access on %I for all using (owner_key = current_setting(''request.headers'', true)::json->>''x-owner-key'') with check (owner_key = current_setting(''request.headers'', true)::json->>''x-owner-key'')',t);end loop;end $$;
